// Stable article binding for the visual editor; no rewriting or new approval.
const rows = $input.all();
if (rows.length !== 1) throw new Error('Visual input: expected one preview');
const p = rows[0].json.body ?? rows[0].json;
if (p.schema !== 'writing_preview.v1' || p.status !== 'draft' || p.editing_status !== 'completed'
    || !p.content_id || !['zh-CN','en-US'].includes(p.language)
    || typeof p.article_markdown !== 'string' || !p.article_markdown.trim()
    || p.publication?.state !== 'NOT_PUBLISHED') {
  throw new Error('Visual input: expected an edited, unpublished preview');
}
return [{json:p,pairedItem:{item:0}}];

// Validate the plan, not the article's ideas. Keep the edited preview on failure.
const preview = $('V2 Visual Input').first().json;
if (preview?.schema !== 'writing_preview.v1' || typeof preview.article_markdown !== 'string') {
  throw new Error('Visual validator: source preview missing');
}
const raw = $input.first().json;
const plan = raw.output ?? raw;
const fail = code => { throw new Error(code); };
const styles = new Set(["SATIRIST_PEN_INK", "ABSTRACT_LINE_RISO", "HALFTONE_PAPER_COLLAGE", "HUMANIST_PAPERCRAFT", "DOCUMENTARY_REALISM", "LUXURY_EDITORIAL", "NEO_BRUTALIST", "MACRO_SILICON", "LINOCUT_EDITORIAL", "DOUBLE_EXPOSURE", "FINE_BITMAP_EDITORIAL", "EDITORIAL_DIORAMA", "RETRO_FUTURIST", "PASTORAL_ANIMATION", "ABSTRACT_FINE_ART"]);
const required = ['id','role','visual_mode','archetype_id','format_preset','purpose','scene','alt_text'];
// Ordinary prose anchors only; preserve Markdown and CRLF source characters.
const paragraphs = [];
let block = [], fence = null;
const flush = () => {
  if (block.length && block.every(l=>!/^(?: {4}| {0,3}(?:#{1,6}\s|>|[-*+]\s|\d+[.)]\s|\||<|(?:[-*_]\s*){3,}$))/.test(l))) paragraphs.push(block.join('\n'));
  block = [];
};
for (const line of preview.article_markdown.split('\n')) {
  const f = line.match(/^ {0,3}(`{3,}|~{3,})/);
  if (f) {
    flush();
    if (!fence) fence = {char:f[1][0],length:f[1].length};
    else if (f[1][0] === fence.char && f[1].length >= fence.length && new RegExp('^ {0,3}'+fence.char+'{'+fence.length+',}\\s*$').test(line)) fence = null;
    continue;
  }
  if (fence) continue;
  if (!line.trim()) flush(); else block.push(line);
}
flush();
try {
  if (raw.error) fail('visual_planner_failed');
  if (!plan || plan.schema !== 'visual_plan.v2' || !Array.isArray(plan.images_to_generate) || !plan.images_to_generate.length) fail('invalid_visual_plan');
  const tasks = plan.images_to_generate, used = new Set();
  let lastPosition = -1;
  tasks.forEach((t,i)=>{
    if (!t || required.some(k=>typeof t[k] !== 'string' || !t[k].trim()) || typeof t.caption !== 'string'
        || !t.placement || typeof t.placement.anchor !== 'string' || Object.hasOwn(t,'prompt')) fail('invalid_visual_task');
    if (t.visual_mode !== 'editorial_image' || !styles.has(t.archetype_id)) fail('unsupported_visual_type');
    used.add(t.archetype_id);
    if (t.id !== (i === 0 ? 'COVER_IMG' : 'IMG_'+i)) fail('invalid_visual_id_order');
    if (i === 0) {
      if (t.role !== 'article_cover' || t.format_preset !== 'linkedin_article_cover'
          || t.placement.mode !== 'cover_field' || t.placement.anchor !== '' || t.caption !== '') fail('invalid_cover');
    } else {
      const a=t.placement.anchor, at=preview.article_markdown.indexOf(a);
      if (t.role !== 'body_illustration' || t.format_preset !== 'inline_square' || t.placement.mode !== 'after_paragraph'
          || !a.trim() || paragraphs.filter(p=>p===a).length !== 1
          || preview.article_markdown.indexOf(a,at+a.length) !== -1 || at <= lastPosition) fail('invalid_body_anchor');
      lastPosition=at;
    }
  });
  if (used.size > 2) fail('incoherent_archetype_count');
  return [{json:{...preview,visual_planning_status:'completed',visual_plan:{
    schema:'visual_plan_validated.v1',status:'PASS',source_plan_schema:'visual_plan.v2',
    final_article:preview.article_markdown,cover_image:tasks[0],body_images:tasks.slice(1),
    images_to_generate:tasks,counts:{total:tasks.length,cover:1,body:tasks.length-1,archetypes:used.size},archetypes_used:[...used]
  }},pairedItem:{item:0}}];
} catch (error) {
  // Sanitized result: a failed illustration plan must not discard either text.
  const known=['visual_planner_failed','invalid_visual_plan','invalid_visual_task','unsupported_visual_type','invalid_visual_id_order','invalid_cover','invalid_body_anchor','incoherent_archetype_count'];
  const code=known.includes(error.message)?error.message:'invalid_visual_plan';
  return [{json:{...preview,visual_planning_status:'failed',visual_plan:null,warnings:[...(preview.warnings||[]),code]},pairedItem:{item:0}}];
}
